// Custom deleter for a C-style file handle.
auto file_deleter = [](FILE* fp) {
    if (fp) {
        fclose(fp);
    }
};
// The deleter's type is part of the unique_ptr's type.
std::unique_ptr<FILE, decltype(file_deleter)> p_file(
    fopen("data.txt", "r"),
    file_deleter
);

// Array specialization using the default deleter (delete[]).
// Note the T[] syntax in the template argument.
std::unique_ptr<int[]> p_array(new int[10]);

// Use the indexing operator, not dereferencing.
for (int i = 0; i < 10; ++i) {
    p_array[i] = i * i;
}
// operator* and operator-> are not available on the array specialization.
// *p_array; // Compile-time error.

// The size of a unique_ptr can be affected by the deleter.
auto stateless_deleter = [](Widget* p){ delete p; };
std::unique_ptr<Widget, decltype(stateless_deleter)> p_w1;
// sizeof(p_w1) is typically sizeof(Widget*)

void (*deleter_func)(Widget*) = [](Widget* p){ delete p; };
std::unique_ptr<Widget, void (*)(Widget*)> p_w2(nullptr, deleter_func);
// sizeof(p_w2) is typically sizeof(Widget*) + sizeof(function_pointer)
